<?php defined('_JEXEC') or die; use Joomla\CMS\HTML\HTMLHelper; use Joomla\CMS\Language\Text; use Joomla\CMS\Router\Route; $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<form action="<?= Route::_('index.php?option=com_decaroevents&view=sessions') ?>" method="post" id="adminForm" name="adminForm"><div class="xdecaro-scope"><div class="xdecaro-table-wrap"><table class="xdecaro-table"><thead><tr><th><?= HTMLHelper::_('grid.checkall') ?></th><th><?= Text::_('COM_DECAROEVENTS_EVENT') ?></th><th><?= Text::_('JGLOBAL_TITLE') ?></th><th><?= Text::_('COM_DECAROEVENTS_FIELD_START') ?></th><th><?= Text::_('COM_DECAROEVENTS_FIELD_CAPACITY') ?></th><th><?= Text::_('JSTATUS') ?></th></tr></thead><tbody><?php foreach($this->items as $i=>$item):?><tr><td><?= HTMLHelper::_('grid.id',$i,(int)$item->id) ?></td><td><?= $e($item->event_title) ?></td><td><a href="<?= Route::_('index.php?option=com_decaroevents&task=session.edit&id='.(int)$item->id) ?>"><?= $e($item->title) ?></a></td><td><?= $e($item->start_at) ?></td><td><?= (int)$item->capacity ?: Text::_('COM_DECAROEVENTS_INHERIT') ?></td><td><?= Text::_((int)$item->published===1?'JPUBLISHED':'JUNPUBLISHED') ?></td></tr><?php endforeach;?></tbody></table></div><?= $this->pagination->getListFooter() ?></div><input type="hidden" name="task" value=""><input type="hidden" name="boxchecked" value="0"><?= HTMLHelper::_('form.token') ?></form>
